<?php require "includes.php";$ok=false;$err="";if($_SERVER["REQUEST_METHOD"]==="POST"){if(empty($_POST["agree"]))$err="Anda harus menyetujui pemrosesan data.";else{$stmt=$pdo->prepare("INSERT INTO pendaftaran(nama,nim,semester,kelas,whatsapp,email,divisi,alasan,agree,status) VALUES(?,?,?,?,?,?,?,?,?, 'Pending')");$stmt->execute([$_POST["nama"],$_POST["nim"],$_POST["semester"],$_POST["kelas"],$_POST["whatsapp"],$_POST["email"],$_POST["divisi"],$_POST["alasan"],1]);$ok=true;}}?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Gabung HMPSIF</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/style_modern.css" rel="stylesheet"></head><body><?php include "navbar.php";?><main class="section"><div class="container"><div class="row g-5"><div class="col-lg-5"><div class="eyebrow">Open Membership</div><h1 class="section-title">Gabung dengan HMPSIF</h1><ol class="mt-4"><li class="mb-3">Baca informasi organisasi.</li><li class="mb-3">Isi formulir pendaftaran.</li><li class="mb-3">Ikuti proses seleksi/orientasi.</li><li class="mb-3">Mengikuti kegiatan penerimaan anggota.</li><li>Resmi menjadi anggota HMPSIF.</li></ol></div><div class="col-lg-7"><?php if($ok):?><div class="alert alert-success">Pendaftaran berhasil dikirim.</div><?php elseif($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?><div class="card card-modern p-4"><form method="post" enctype="multipart/form-data"><div class="row g-3"><?php foreach([["nama","Nama Lengkap"],["nim","NIM"],["semester","Semester"],["kelas","Kelas"],["whatsapp","Nomor WhatsApp"],["email","Email"]] as $f):?><div class="col-md-6"><label class="form-label"><?=$f[1]?></label><input required name="<?=$f[0]?>" class="form-control"></div><?php endforeach;?><div class="col-md-6"><label class="form-label">Divisi yang diminati</label><select name="divisi" class="form-select" required><?php foreach(["PSDM","Pendidikan","Kominfo","Humas","Minat dan Bakat"] as $x):?><option><?=$x?></option><?php endforeach;?></select></div><div class="col-12"><label class="form-label">Alasan bergabung</label><textarea name="alasan" required class="form-control" rows="4"></textarea></div><div class="col-12"><label><input type="checkbox" name="agree" required> Saya menyetujui pemrosesan data untuk keperluan pendaftaran.</label></div><div class="col-12"><button class="btn btn-primary btn-lg rounded-pill">Daftar Sekarang</button></div></div></form></div></div></div></div></main><?php include "footer.php";?></body></html>